export function parseNames(text: string): string[] {
 const body = JSON.parse(text) as { names: string[] }
 return body.names.map(name => name.trim())
}

export function parseName(text: string): string {
 const body: unknown = JSON.parse(text)
 if (!body || typeof body !== 'object' || !('name' in body) || typeof body.name !== 'string') throw new Error('Invalid name')
 return body.name.trim()
}

